/** Render complete valid ballots as readable text while preserving other messages verbatim. */
export function readableRoomMessage(body) {
    try {
        const value = JSON.parse(body);
        if (!value || typeof value !== 'object' || Array.isArray(value))
            return body;
        const ballot = value;
        if (Object.keys(ballot).some(key => !['vote', 'rationale', 'assignments'].includes(key)) || !['approve', 'revise', 'abstain'].includes(String(ballot.vote)) || typeof ballot.rationale !== 'string' || !ballot.assignments || typeof ballot.assignments !== 'object' || Array.isArray(ballot.assignments))
            return body;
        const assignments = Object.entries(ballot.assignments);
        if (assignments.some(([, agent]) => typeof agent !== 'string'))
            return body;
        const votes = { approve: 'Approve', revise: 'Request revision', abstain: 'Abstain' };
        return [`Vote: ${votes[String(ballot.vote)]}`, '', 'Rationale', ballot.rationale, '', 'Assignments', ...assignments.map(([task, agent]) => `${task} → ${agent}`), ...(assignments.length ? [] : ['No task assignments proposed.'])].join('\n');
    }
    catch {
        return body;
    }
}
