var labels={idle:'Not started',discussing:'Discussion in progress',ready:'Plan approved',running:'Tasks in progress',paused:'Paused',completed:'Completed',failed:'Failed',cancelled:'Cancelled',needs_attention:'Needs attention',pending:'Pending assignment',assigned:'Assigned'};
