function draftFor(id){if(!drafts.has(id))drafts.set(id,{messageAuthor:'PM',messageBody:'',taskTitle:'',taskBrief:'',taskPermission:'read',taskDependency:'',messageGeneration:0,taskGeneration:0});return drafts.get(id);}
