function clearRoomDraft(id,kind,generation){var draft=drafts.get(id),key=kind==='message'?'messageGeneration':'taskGeneration';if(!draft||draft[key]!==generation)return false;var changes=kind==='message'?{messageBody:''}:{taskTitle:'',taskBrief:'',taskPermission:'read',taskDependency:''};Object.keys(changes).forEach(function(field){draft[field]=changes[field];if(draftOwner===id)$(field).value=changes[field];});draft[key]++;return true;}
