function invalidateHistory(){historyEpoch++;if(historyController)historyController.abort();historyController=undefined;historyBusy=false;historyOpen=false;updateHistoryControls();}
function dismissHistory(){invalidateHistory();$('historyDialog').close();}
function invalidateCreateDialog(){createEpoch++;$('createSubmit').disabled=createPending.has(createEpoch);}
