async function loadRoom(id){var request=++loading;if(selected!==id){saveVisibleDrafts();selectionEpoch++;invalidateHistory();historyMessages=[];historyCursor=null;historyAfter=0;}roomLoading=!room||room.id!==id;selected=id;renderList(roomList);controls();try{var next=await api('/api/rooms/'+encodeURIComponent(id));if(request!==loading||selected!==id)return;if(!room||room.id!==id||next.revision>=room.revision){room=next;renderRoom();restoreDraft(id);}}catch(e){if(request===loading&&selected===id)error(e.message);}finally{if(request===loading&&selected===id){roomLoading=false;controls();updateHistoryControls();}}}
async function refreshList(signal){var generation=++roomListGeneration,list=await api('/api/rooms',undefined,signal);if(generation!==roomListGeneration||signal&&signal.aborted)return;renderList(list);if(selected){var summary=list.find(function(item){return item.id===selected;});if(summary&&(!room||room.id!==selected||summary.revision!==room.revision))await loadRoom(selected);}}
function requestTarget(){return !room||busy||roomLoading||room.id!==selected?null:{id:room.id,epoch:selectionEpoch};}
function sameTarget(target){return !!target&&selected===target.id&&selectionEpoch===target.epoch&&!roomLoading&&!!room&&room.id===target.id;}
function applyRoomResponse(next,target){if(!sameTarget(target)||next.id!==target.id)return false;if(next.revision>=room.revision){room=next;renderRoom();restoreDraft(target.id);}return true;}
async function perform(action){var target=requestTarget();if(!target)return;busy=true;clearError();controls();try{var next=await api('/api/rooms/'+encodeURIComponent(target.id)+'/'+action,{});applyRoomResponse(next,target);await refreshList();}catch(e){if(sameTarget(target))error(e.message);}finally{busy=false;controls();}}
function option(value,text){var node=element('option','',text);node.value=value;return node;}
function formField(title,input){var label=element('label','field');label.append(element('span','',title),input);return label;}
function updateMemberRows(){var rows=Array.from($('memberRows').children),advisors=rows.filter(function(row){return row.querySelector('.member-role').value==='advisor';}).map(function(row){return row.querySelector('.member-agent').value;});$('addMember').disabled=rows.length>=agents.length;rows.forEach(function(row){row.querySelector('.remove-member').disabled=rows.length<=1;var select=row.querySelector('.member-advisor'),previous=select.value,own=row.querySelector('.member-agent').value;select.replaceChildren(option('','No advisor'));advisors.filter(function(alias){return alias!==own;}).forEach(function(alias){select.append(option(alias,alias));});if(advisors.includes(previous)&&previous!==own)select.value=previous;select.disabled=row.querySelector('.member-role').value==='advisor';if(select.disabled)select.value='';row.querySelector('.member-advisor-quota').disabled=select.disabled||!select.value;select.title='To consult a profile, add it to the group with the Advisor role.';});}
function addMember(preferred){var row=element('div','member-row'),select=element('select','member-agent'),role=element('select','member-role'),weight=element('input','member-weight'),model=element('input','member-model'),effort=element('select','member-effort'),advisor=element('select','member-advisor'),advisorQuota=element('input','member-advisor-quota'),skillsNote=element('span','field-note member-skills-note');skillsNote.hidden=true;agents.forEach(function(a){select.append(option(a.agent,a.agent+' · '+a.profile));});select.value=preferred||agents[0].agent;role.append(option('lead','Lead'),option('worker','Worker'),option('advisor','Advisor'));role.value=$('memberRows').children.length?'worker':'lead';weight.type='number';weight.min='0';weight.step='any';weight.required=true;model.placeholder='Native model';effort.append(option('','Native setting'));['low','medium','high','xhigh','max'].forEach(function(value){effort.append(option(value,value));});advisor.append(option('','No advisor'));advisorQuota.type='number';advisorQuota.min='1';advisorQuota.step='1';advisorQuota.value='1';advisorQuota.required=true;advisor.addEventListener('change',updateMemberRows);var remove=element('button','remove-member','×');remove.type='button';remove.setAttribute('aria-label','Remove member');remove.addEventListener('click',function(){createDraftGeneration++;row.remove();updateMemberRows();});function defaults(){var config=agents.find(function(a){return a.agent===select.value;});if(!config)return;weight.value=String(config.authority||1);model.value=config.model||'';effort.value=config.effort||'';}select.addEventListener('change',function(){delete row.dataset.routingSkills;skillsNote.hidden=true;defaults();updateMemberRows();});role.addEventListener('change',updateMemberRows);defaults();row.append(formField('Agent',select),formField('Role',role),formField('Weight',weight),formField('Model',model),formField('Effort',effort),formField('Advisor for this member',advisor),formField('Advisor requests',advisorQuota),remove,skillsNote);$('memberRows').append(row);createDraftGeneration++;updateMemberRows();}
function openCreate(){if(!agents.length){error('There are no enabled agents. Configure at least one project profile.');return;}createEpoch++;routingReset();$('createSubmit').disabled=createPending.has(createEpoch);$('createError').hidden=true;$('createStatus').hidden=true;if(!$('memberRows').children.length){addMember(agents[0].agent);if(agents.length>1)addMember(agents[1].agent);}$('createDialog').showModal();$('createRoomTitle').focus();}
